// Directly adapted from Dime SettingsView's SettingsRowView grouped-row language.
import SwiftUI
struct DimeSettingsRow: View { let icon:String; let title:LocalizedStringKey; let detail:LocalizedStringKey?; var body:some View{HStack(spacing:12){Image(systemName:icon).font(.system(.body,design:.rounded).weight(.semibold)).frame(width:30,height:30).foregroundColor(Color.DarkIcon).background(Color.SecondaryBackground,in:RoundedRectangle(cornerRadius:8));VStack(alignment:.leading,spacing:2){Text(title).font(.system(.body,design:.rounded).weight(.medium));if let detail{Text(detail).font(.system(.subheadline,design:.rounded)).foregroundColor(Color.SubtitleText)}};Spacer();Image(systemName:"chevron.forward").font(.system(.caption,design:.rounded)).foregroundColor(Color.SubtitleText)}.foregroundColor(Color.PrimaryText).contentShape(Rectangle())} }
struct DimeSettingsSection<Content:View>:View{let title:LocalizedStringKey;@ViewBuilder let content:Content;var body:some View{VStack(alignment:.leading,spacing:5){Text(title).font(.system(.footnote,design:.rounded).weight(.semibold)).foregroundColor(Color.SubtitleText).padding(.horizontal,10);VStack(spacing:13){content}.padding(10).background(Color.SecondaryBackground,in:RoundedRectangle(cornerRadius:9,style:.continuous))}.padding(.horizontal,20).padding(.bottom,25)}}
